// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        vm.roll(100);
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(101))));

        vm.roll(102);
        vm.prank(alice);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
